const FILLER_RE = /\b(um+|uh+|erm+|ah+|you know|i mean|kind of|sort of)\b/gi;
const SERVICE_RE = /\[(inaudible|unintelligible|music|laughter|applause|silence|blank_audio)\]/gi;
const RECORDING_NOTICE_RE = /this (meeting|call|conversation) is being recorded\.?/gi;

function cleanText(text) {
  return String(text || '')
    .replace(SERVICE_RE, ' ')
    .replace(RECORDING_NOTICE_RE, ' ')
    .replace(FILLER_RE, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function formatUtterance(utterance) {
  const cleaned = cleanText(utterance.text);
  if (!cleaned) return '';
  const ts =
    utterance.start != null
      ? `[${utterance.start}${utterance.end != null ? `-${utterance.end}` : ''}] `
      : '';
  const speaker = utterance.speaker_id ? `${utterance.speaker_id}: ` : '';
  return `${ts}${speaker}${cleaned}`.trim();
}

function chunkText(text, maxChars = 6000) {
  const source = String(text || '').trim();
  if (!source) return [];
  if (source.length <= maxChars) {
    return [{ chunk_index: 0, text: source, start_offset: 0, end_offset: source.length }];
  }

  const chunks = [];
  let cursor = 0;
  let index = 0;
  while (cursor < source.length) {
    let end = Math.min(cursor + maxChars, source.length);
    if (end < source.length) {
      const window = source.lastIndexOf('\n', end);
      const sentence = source.lastIndexOf('. ', end);
      const splitAt = Math.max(window, sentence);
      if (splitAt > cursor + Math.floor(maxChars * 0.4)) end = splitAt + 1;
    }
    const slice = source.slice(cursor, end).trim();
    if (slice) {
      chunks.push({
        chunk_index: index,
        text: slice,
        start_offset: cursor,
        end_offset: end,
      });
      index += 1;
    }
    cursor = end;
  }
  return chunks;
}

function preprocessTranscript(input, options = {}) {
  const maxChars = options.maxChars || 6000;
  const text = input?.text || '';
  const utterances = Array.isArray(input?.utterances) ? input.utterances : [];
  const lines = utterances.length
    ? utterances.map(formatUtterance).filter(Boolean)
    : [cleanText(text)];
  const cleanedText = lines.join('\n').trim();
  const chunks = chunkText(cleanedText, maxChars).map((chunk, _, all) => ({
    ...chunk,
    chunk_total: all.length,
  }));

  return {
    cleaned_text: cleanedText,
    chunks,
    utterance_count: utterances.length,
    too_short: cleanedText.length < 40,
  };
}

const item = $input.first().json;
const processed = preprocessTranscript(item, { maxChars: 6000 });
if (!processed.chunks.length) {
  processed.chunks = [{
    chunk_index: 0,
    chunk_total: 1,
    text: processed.cleaned_text || '(empty transcript)',
    start_offset: 0,
    end_offset: 0,
  }];
}
return [{ json: { meeting: item.meeting, utterances: item.utterances || [], ...processed } }];

function isHttpError(item) {
  if (!item || typeof item !== 'object') return true;
  if (item.error) return true;
  const status = item.statusCode || item.status;
  if (status && Number(status) >= 400) return true;
  return false;
}

function assembleContext({ meeting, jiraItem, confluenceItem }) {
  const warnings = [];
  const jiraRequested = Boolean(meeting?.jira_epic_id);
  const confluenceRequested = Boolean(meeting?.project_id);

  let jira = { issues: [], epic: null, available: false };
  if (jiraRequested && !jiraItem?.jira_skipped) {
    if (isHttpError(jiraItem)) {
      warnings.push('jira_unavailable');
    } else {
      jira = {
        available: true,
        epic: jiraItem.epic || jiraItem.key ? jiraItem : jiraItem.issues ? jiraItem.epic : jiraItem,
        issues: jiraItem.issues || jiraItem.fields ? [jiraItem] : [],
      };
    }
  }

  let confluence = { pages: [], available: false };
  if (confluenceRequested && !confluenceItem?.confluence_skipped) {
    if (isHttpError(confluenceItem)) {
      warnings.push('confluence_unavailable');
    } else {
      const results = confluenceItem.results || confluenceItem.pages || confluenceItem.contents || [];
      confluence = { available: true, pages: results };
    }
  }

  const incomplete = warnings.length > 0;
  const contextText = [
    incomplete ? 'CONTEXT STATUS: INCOMPLETE — generate the ADR anyway and mention missing systems.' : 'CONTEXT STATUS: complete',
    jiraRequested ? `JIRA EPIC: ${meeting.jira_epic_id}` : 'JIRA: not requested',
    jira.available ? `JIRA DATA: ${JSON.stringify(jira).slice(0, 4000)}` : warnings.includes('jira_unavailable') ? 'JIRA DATA: unavailable' : '',
    confluenceRequested ? `CONFLUENCE PROJECT: ${meeting.project_id}` : 'CONFLUENCE: not requested',
    confluence.available ? `CONFLUENCE DATA: ${JSON.stringify(confluence).slice(0, 4000)}` : warnings.includes('confluence_unavailable') ? 'CONFLUENCE DATA: unavailable' : '',
    `OPTIONAL RAG STANDARDS: ${(meeting.architectural_standards || []).join(', ') || 'none (MVP, vector store not required)'}`,
  ]
    .filter(Boolean)
    .join('\n');

  return {
    jira,
    confluence,
    warnings,
    incomplete,
    context_text: contextText,
    architectural_standards: meeting?.architectural_standards || [],
  };
}

const processed = $('Preprocess and Chunk').first().json;
const merged = $input.first().json;
const context = assembleContext({
  meeting: processed.meeting,
  jiraItem: merged.jiraItem || { jira_skipped: true },
  confluenceItem: merged.confluenceItem || { confluence_skipped: true },
});
return [{ json: { ...processed, context } }];

